import { contentHash,type DimensionDefinition,type ModelContent } from "@/lib/gdss/core";
import { EVALUATOR_VERSION,EXPRESSION_LANGUAGE_VERSION,UNIT_CONVERSION_CATALOG_V2,UNIT_CONVERSION_CATALOG_VERSION_V2 } from "@/lib/gdss/expression";
import { CONSTRAINT_POLICY,DYNAMIC_SEMANTIC_VERSION,GDSS_SIM_LIMITS_V1,SOLVER_VERSION,dynamicBindingHash,type DynamicBindingContent,type DynamicBindingSnapshot,type SimulationInputManifest } from "@/lib/gdss/simulation";

const provenance=[{kind:"HUMAN_PROPOSED" as const,description:"P016-R2 exact reservoir and thermal governed fixture",asserted_by:"p016-r2",metadata:{}}];
const scalar:DimensionDefinition=[0,0,0,0,0,0,0],rate:DimensionDefinition=[0,0,-1,0,0,0,0],volume:DimensionDefinition=[3,0,0,0,0,0,0],flow:DimensionDefinition=[3,0,-1,0,0,0,0],temperature:DimensionDefinition=[0,0,0,1,0,0,0],temperatureRate:DimensionDefinition=[0,0,-1,1,0,0,0];
const unit=(key:string,symbol:string,dimension:DimensionDefinition)=>{const catalog=UNIT_CONVERSION_CATALOG_V2[`${key}@1`];if(catalog){const{quantitySemantics:_quantitySemantics,affineFamily:_affineFamily,...definition}=catalog;return structuredClone(definition);}return{key,revision:1,symbol,name:key,dimension,scale:1,offset:0,canonical_unit:key};};
const state=(symbol:string,unit_ref:string,dimension:DimensionDefinition)=>({kind:"Variable" as const,symbol,label:symbol,description:"governed state",provenance,unit_ref,dimension,computational_role:"STATE" as const,epistemic_kind:"SIMULATED" as const});
const output=(symbol:string,unit_ref:string,dimension:DimensionDefinition)=>({kind:"Variable" as const,symbol,label:symbol,description:"governed rate output",provenance,unit_ref,dimension,computational_role:"AUXILIARY" as const,epistemic_kind:"DERIVED" as const});
const parameter=(symbol:string,unit_ref:string,dimension:DimensionDefinition,value:number)=>({kind:"Parameter" as const,symbol,label:symbol,description:"governed fixture parameter",provenance,unit_ref,dimension,default_value:value,valid_range:[0,200] as [number,number]});
const formula=(symbol:string,expression_source:string,input_refs:string[],output_ref:string)=>({kind:"Formula" as const,symbol,label:symbol,description:"governed rate equation",provenance,expression_source,input_refs,output_ref,validity_domain:{}});

export const R1_STATE_SYMBOLS=["V","T","x1","x2","x3","x4","x5","x6"] as const;
export const R1_PARAMETER_SYMBOLS=["Qout","k","p3","p4"] as const;
export const R1_TRUTH={Qout:1,k:1,p3:1,p4:2} as const;
export const R2_STEP_SECONDS=0.001;

export function r1Model():ModelContent{
  const auxiliaryStates=["x1","x2","x3","x4","x5","x6"].flatMap((symbol,index)=>{const p=index%2===0?"p3":"p4";return[state(symbol,"one",scalar),output(`${symbol}_rate`,`per_second`,rate),formula(`${symbol}_formula`,p,[p],`${symbol}_rate`)];});
  return{description:"P016-R2 literal dV/dt=Qin-Qout and dT/dt=-k(T-Tambient) fixture",validity_domain:{},provenance,units:[unit("one","1",scalar),unit("per_second","1/s",rate),unit("cubic_meter","m3",volume),unit("cubic_meter_per_second","m3/s",flow),unit("kelvin","K",temperature),unit("kelvin_per_second","K/s",temperatureRate)],children:[state("V","cubic_meter",volume),output("dV","cubic_meter_per_second",flow),formula("reservoir_rate_formula","Qin - Qout",["Qin","Qout"],"dV"),state("T","kelvin",temperature),output("dT","kelvin_per_second",temperatureRate),formula("thermal_rate_formula","-k * (T - Tambient)",["k","T","Tambient"],"dT"),...auxiliaryStates,parameter("Qin","cubic_meter_per_second",flow,3),parameter("Qout","cubic_meter_per_second",flow,R1_TRUTH.Qout),parameter("Tambient","kelvin",temperature,20),parameter("k","per_second",rate,R1_TRUTH.k),parameter("p3","per_second",rate,R1_TRUTH.p3),parameter("p4","per_second",rate,R1_TRUTH.p4)]};
}

export function r1Binding(projectId:string,modelIdentityId:string,modelVersionId:string,bindingId:string,bindingVersionId:string,model=r1Model()):DynamicBindingSnapshot{
  const modelContentHash=contentHash(model),stateUnits:Record<string,{unit:{key:string;revision:number};dimension:DimensionDefinition}>={V:{unit:{key:"cubic_meter",revision:1},dimension:volume},T:{unit:{key:"kelvin",revision:1},dimension:temperature},...Object.fromEntries(["x1","x2","x3","x4","x5","x6"].map(symbol=>[symbol,{unit:{key:"one",revision:1},dimension:scalar}]))},rateUnits:Record<string,{unit:{key:string;revision:number};dimension:DimensionDefinition}>={V:{unit:{key:"cubic_meter_per_second",revision:1},dimension:flow},T:{unit:{key:"kelvin_per_second",revision:1},dimension:temperatureRate},...Object.fromEntries(["x1","x2","x3","x4","x5","x6"].map(symbol=>[symbol,{unit:{key:"per_second",revision:1},dimension:rate}]))};
  const content:DynamicBindingContent={projectId,modelVersionId,modelContentHash,dynamicSemanticVersion:DYNAMIC_SEMANTIC_VERSION,states:R1_STATE_SYMBOLS.map(symbol=>({role:"STATE",stateRef:symbol,...stateUnits[symbol],constraintRefs:[]})),rates:R1_STATE_SYMBOLS.map(symbol=>({role:"RATE",rateRef:`${symbol}_rate_binding`,stateRef:symbol,formulaRef:symbol==="V"?"reservoir_rate_formula":symbol==="T"?"thermal_rate_formula":`${symbol}_formula`,outputRef:symbol==="V"?"dV":symbol==="T"?"dT":`${symbol}_rate`,...rateUnits[symbol]})),algebraics:[],parameters:["Qin","Qout","Tambient","k","p3","p4"].map(parameterRef=>({role:"PARAMETER",parameterRef})),constraintRefs:[],provenanceIdentities:[`p016-r2:${modelIdentityId}`]};
  return{...content,bindingId,bindingVersionId,bindingVersion:1,dynamicBindingHash:dynamicBindingHash(content),lifecycleStatus:"PUBLISHED",model};
}

export function r1Manifest(binding:DynamicBindingSnapshot,values:Record<string,number>,stepCount:number):SimulationInputManifest{
  const governedValues={Qin:3,Qout:R1_TRUTH.Qout,Tambient:20,k:R1_TRUTH.k,p3:R1_TRUTH.p3,p4:R1_TRUTH.p4,...values};
  return{projectId:binding.projectId,modelVersionId:binding.modelVersionId,modelContentHash:binding.modelContentHash,bindingId:binding.bindingId,bindingVersionId:binding.bindingVersionId,bindingVersion:binding.bindingVersion,dynamicBindingHash:binding.dynamicBindingHash,dynamicSemanticVersion:DYNAMIC_SEMANTIC_VERSION,solverVersion:SOLVER_VERSION,initialConditions:R1_STATE_SYMBOLS.map(ref=>({ref,value:ref==="V"?10:ref==="T"?100:0,unit:{key:ref==="V"?"cubic_meter":ref==="T"?"kelvin":"one",revision:1},provenanceIdentity:`p016-r2:initial:${ref}`})),parameterValues:Object.entries(governedValues).map(([ref,value])=>({ref,value,unit:{key:ref==="Qin"||ref==="Qout"?"cubic_meter_per_second":ref==="Tambient"?"kelvin":"per_second",revision:1},provenanceIdentity:`p016-r2:parameter:${ref}`})),temporalConfiguration:{start:0,step:R2_STEP_SECONDS,stepCount,timeUnit:{key:"second",revision:1},unitConversionCatalogVersion:UNIT_CONVERSION_CATALOG_VERSION_V2},expressionLanguageVersion:EXPRESSION_LANGUAGE_VERSION,evaluatorVersion:EVALUATOR_VERSION,unitConversionCatalogVersion:UNIT_CONVERSION_CATALOG_VERSION_V2,resourceProfile:GDSS_SIM_LIMITS_V1,constraintPolicy:CONSTRAINT_POLICY};
}

export const r1Dimensions={scalar,rate,volume,flow,temperature,temperatureRate};
